// @vitest-environment jsdom
// The actual App mount seam, actual native client→Host, Plan reader/inspection,
// source port, durable controller/store and widget. Only the native boundary
// returns real disposable-Git owner output generated by the committed Python
// fixture. It is not an App mount, enrollment, network or live adoption claim.
import {act,cleanup,fireEvent,render,screen,waitFor,within} from '@testing-library/react';
import {afterEach,beforeEach,expect,it,vi} from 'vitest';
import {IDBFactory} from 'fake-indexeddb';
import actual from '../fixtures/plan-adoption-installed-journey.json';
import {bindMissionHost,createNativeClient} from '../host';
import {ProjectPlanPanel} from './ProjectPlanPanel';
import {PlanAdoptionWorkflow} from './PlanAdoptionWorkflow';

beforeEach(async()=>{
 const {webcrypto}=await vi.importActual<{webcrypto:Crypto}>('node:crypto');
 vi.stubGlobal('crypto',webcrypto);vi.stubGlobal('indexedDB',new IDBFactory());
 vi.spyOn(crypto,'getRandomValues').mockImplementation(value=>{(value as Uint8Array).fill(0x99);return value;});
});
afterEach(()=>{cleanup();vi.restoreAllMocks();vi.unstubAllGlobals();});
async function setup(){
 let notify!:(event:{payload:unknown})=>void;
 let phase:'candidate'|'ready'|'adoption'|'accepted'='candidate';
 const invoke=vi.fn(async(name:string,args?:unknown)=>{
  if(name==='auth_status')return {status:'signed_in',reason:null,acquisition:true,content:true};
  if(name==='executive_auth_status')return {generation:0,available:false};
  if(name==='read_project_plan')return phase==='accepted'?actual.body:actual.initial_read;
  if(name==='read_source_operation_context')return actual.context;
  if(name==='source_operation_prepare'){
   expect(args).toEqual({request:{action:'ADOPT_PLAN',request:actual.request}});return actual.preview;
  }
  if(name==='source_operation_submit'){
   expect(args).toEqual({request:{...actual.preview.selection,preview_witness:actual.preview.preview_witness}});
   return actual.pending_candidate;
  }
  if(name==='source_operation_read'){
   expect(args).toEqual({request:{schema:'mastermind.workspace_source_operation_lookup.v1',...actual.preview.selection}});
   return phase==='candidate'?actual.pending_candidate:phase==='ready'?actual.ready:phase==='adoption'?actual.pending_adoption:actual.status;
  }
  if(name==='source_operation_reconcile'){
   expect(args).toEqual({request:{schema:'mastermind.workspace_source_operation_lookup.v1',...actual.preview.selection}});
   if(phase==='candidate'){phase='ready';return actual.ready;}
   if(phase==='adoption'){phase='accepted';return actual.status;}
   throw Error('Unexpected observational effect');
  }
  if(name==='source_operation_advance'){
   expect(args).toEqual({request:{schema:'mastermind.workspace_source_operation_advance.v1',...actual.preview.selection,...actual.ready.advance}});
   phase='adoption';return actual.pending_adoption;
  }
  throw Error('Unexpected native command');
 });
 const raw=await createNativeClient(invoke as never,async(_name,listener)=>{notify=listener;return()=>{};});
 const host=bindMissionHost(raw);
 const read=host.readProjectPlan!;
 const generation=()=>host.invalidationGeneration!();
 const canRead=()=>host.auth!.getState().status==='signed_in'&&host.auth!.getState().acquisition===true;
 const selection={work_ref:actual.request.work_ref};
 const view=render(<ProjectPlanPanel selection={selection} read={read} sourceGeneration={generation} canRead={canRead}
  renderWorkspace={({panel,inspection})=><>{panel}<PlanAdoptionWorkflow host={host} workRef={selection.work_ref} inspection={inspection}/></>}/>);
 return {invoke,host,notify,view};
}
async function prepare(){
 await waitFor(()=>expect((screen.getByRole('button',{name:'Review adoption'}) as HTMLButtonElement).disabled).toBe(false));
 fireEvent.click(screen.getByRole('button',{name:'Review adoption'}));
 await screen.findByRole('button',{name:'Adopt this plan'});
}
it('joins exact current READ→Review→explicit Adopt→same-original Check/Advance→final READ/Compare',async()=>{
 const e=await setup();await prepare();
 expect(e.invoke.mock.calls.filter(([name])=>name==='read_project_plan')).toHaveLength(1);
 expect(e.invoke.mock.calls.some(([name])=>name==='source_operation_submit'||name==='source_operation_reconcile'||name==='source_operation_advance')).toBe(false);
 fireEvent.click(screen.getByRole('button',{name:'Adopt this plan'}));
 await screen.findByText(/original adoption outcome is not known yet/);
 fireEvent.click(screen.getByRole('button',{name:'Check original operation'}));
 await screen.findByRole('button',{name:'Continue original adoption'});
 expect(screen.queryByText(/Publication of the original adoption is confirmed/)).toBeNull();
 fireEvent.click(screen.getByRole('button',{name:'Continue original adoption'}));
 await screen.findByText(/original adoption outcome is not known yet/);
 fireEvent.click(screen.getByRole('button',{name:'Check original operation'}));
 await screen.findByText(/Publication of the original adoption is confirmed/);
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_submit')).toHaveLength(1);
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_advance')).toHaveLength(1);
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_reconcile')).toHaveLength(2);
 // A current DEC display still needs its own actual READ; the receipt does
 // not replace it or silently re-read the plan on mutation settlement.
 expect(e.invoke.mock.calls.filter(([name])=>name==='read_project_plan')).toHaveLength(1);
 fireEvent.click(screen.getByRole('button',{name:'Refresh'}));
 await waitFor(()=>expect(e.invoke.mock.calls.filter(([name])=>name==='read_project_plan')).toHaveLength(2));
 await screen.findAllByText('DEC:PLAN-ADOPTION-'+'9'.repeat(40));
 expect(screen.getByText('Compared against the recorded predecessor plan.')).toBeTruthy();
});
it('does not submit a prepared original after live native permission withdrawal',async()=>{
 const e=await setup();await prepare();
 act(()=>e.notify({payload:{status:'signed_out',reason:'AUTHENTICATION_REQUIRED',acquisition:false,content:false}}));
 const adopt=screen.queryByRole('button',{name:'Adopt this plan'});
 if(adopt)fireEvent.click(adopt);
 await act(async()=>{});
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_submit')).toHaveLength(0);
 expect(screen.queryByText(/Publication of the original adoption is confirmed/)).toBeNull();
});

it('refuses a prepared effect on same-host generation drift without a render',async()=>{
 const e=await setup();await prepare();
 const adopt=screen.getByRole('button',{name:'Adopt this plan'});
 vi.spyOn(e.host,'invalidationGeneration').mockReturnValue(99);
 fireEvent.click(adopt);await act(async()=>{});
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_submit')).toHaveLength(0);
 expect(e.invoke.mock.calls.filter(([name])=>name==='source_operation_advance')).toHaveLength(0);
});
